from scipy.optimize import least_squares
def base(p): return p[0]*t**2 + p[1]*(t/(1+p[2]*t))*A**2 + p[3]*np.exp(-p[4]*A**2)
def run(fn,n,trials=10):
    best=None
    for s in range(trials):
        p0=np.random.RandomState(s).uniform(-1,1,n)
        try:
            rr=least_squares(lambda p: fn(p)-dA_dt,p0,max_nfev=1000)
            if best is None or rr.cost<best.cost: best=rr
        except Exception: pass
    return np.mean(best.fun**2)/np.var(dA_dt), np.round(best.x,4)
